function icon(name,size=19){const p={home:'M3 10.5 12 3l9 7.5v9a1.5 1.5 0 0 1-1.5 1.5h-15A1.5 1.5 0 0 1 3 19.5z M9 21v-6h6v6',orders:'M6 3h12v18H6z M9 7h6 M9 11h6 M9 15h4',chat:'M20 15a4 4 0 0 1-4 4H9l-5 3v-7a4 4 0 0 1-2-3.5V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4z',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',user:'M20 21a8 8 0 0 0-16 0 M12 13a5 5 0 1 0 0-10 5 5 0 0 0 0 10',settings:'M12 15.5A3.5 3.5 0 1 0 12 8a3.5 3.5 0 0 0 0 7.5 M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-2.1 2.1-.06-.06a1.7 1.7 0 0 0-1.88-.34 1.7 1.7 0 0 0-1.03 1.56V20h-3v-.09A1.7 1.7 0 0 0 10.7 18.35a1.7 1.7 0 0 0-1.88.34l-.06.06-2.1-2.1.06-.06A1.7 1.7 0 0 0 7.06 14.7 1.7 1.7 0 0 0 5.5 13.67H5.4v-3h.1A1.7 1.7 0 0 0 7.06 9.64a1.7 1.7 0 0 0-.34-1.88l-.06-.06 2.1-2.1.06.06a1.7 1.7 0 0 0 1.88.34 1.7 1.7 0 0 0 1.03-1.56V4.3h3v.1a1.7 1.7 0 0 0 1.03 1.56 1.7 1.7 0 0 0 1.88-.34l.06-.06 2.1 2.1-.06.06a1.7 1.7 0 0 0-.34 1.88 1.7 1.7 0 0 0 1.56 1.03h.1v3h-.1A1.7 1.7 0 0 0 19.4 15',search:'m21 21-4.3-4.3 M10.8 18a7.2 7.2 0 1 1 0-14.4 7.2 7.2 0 0 1 0 14.4',wrench:'M14.7 6.3a4 4 0 0 0-5 5L3 18l3 3 6.7-6.7a4 4 0 0 0 5-5l-2.8 2.1-2.3-2.3z',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z',heart:'M20.8 8.6C20.8 14.5 12 20 12 20S3.2 14.5 3.2 8.6A4.5 4.5 0 0 1 12 7a4.5 4.5 0 0 1 8.8 1.6',check:'m5 12 4.2 4.2L19 6.5',arrow:'M19 12H5 M11 18l-6-6 6-6',credit:'M3 6h18v12H3z M3 10h18 M7 16h3',support:'M4 13a8 8 0 0 1 16 0v5a3 3 0 0 1-3 3h-2 M4 13v5a2 2 0 0 0 2 2h1v-8H4 M20 13v5a2 2 0 0 1-2 2h-1v-8h3'}[name]||'M3 12h18';return `<svg class="ico" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="${p}"/></svg>`}
const serviceIcon=(service='')=>{const key=String(service).toLowerCase(),paths=key.includes('electric')?'M13 2 5 13h6l-1 9 9-12h-6z':key.includes('plumb')?'M8 3v7a4 4 0 1 0 8 0V7 M5 3h6 M13 7h6 M8 17h8':key.includes('clean')?'M5 20 16 9 M14 5l5 5 M3 22h6':key.includes('ac')?'M4 5h16v11H4z M7 9h10 M8 13h8 M9 19h6':key.includes('paint')?'M4 19h15 M7 16l7-7 3 3-7 7H7z M14 9l2-2 3 3-2 2':key.includes('carp')?'M4 17 17 4l3 3L7 20 M3 21l4-1':key.includes('internet')?'M3 18a13 13 0 0 1 18 0 M6 14a9 9 0 0 1 12 0 M9 10a5 5 0 0 1 6 0 M12 21h.01':key.includes('moving')?'M3 7h11v10H3z M14 11h4l3 3v3h-7 M7 20a2 2 0 1 0 0-4 2 2 0 0 0 0 4 M18 20a2 2 0 1 0 0-4 2 2 0 0 0 0 4':key.includes('pest')?'M12 8v12 M8 12h8 M7 6l2 2 M17 6l-2 2 M5 14l3-1 M19 14l-3-1 M8 20l-2 2 M16 20l2 2':icon('wrench',24).match(/<path d="([^"]+)/)?.[1]||'';return `<svg class="ico service-glyph" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="${paths}"/></svg>`};
const fileData=file=>new Promise((resolve,reject)=>{if(!file)return resolve(null);if(file.size>1500000)return reject(Error('الصورة أكبر من 1.5MB.'));const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('تعذر قراءة الصورة.'));reader.readAsDataURL(file)});
const chatFileData=file=>new Promise((resolve,reject)=>{if(!file)return resolve(null);if(file.type?.startsWith('video/'))return reject(Error(t('videoNotAllowed')));if(file.size>4000000)return reject(Error(t('fileTooLarge')));const reader=new FileReader();reader.onload=()=>resolve({name:file.name||'attachment',mime:file.type||'application/octet-stream',data:reader.result,size:file.size});reader.onerror=()=>reject(Error(t('fileReadError')));reader.readAsDataURL(file)});
function setLang(){const theme=S.theme||'light';document.documentElement.lang=S.lang;document.documentElement.dir=rtl()?'rtl':'ltr';document.documentElement.dataset.theme=theme;localStorage.setItem('engedny-lang',S.lang);localStorage.setItem('engedny-theme',theme)}
function shell(content){const nav=[['home','home'],['orders','orders'],['chat','chat'],['notifications','bell'],['profile','user'],['settings','settings']];return `<main class="shell view-${S.view} ${S.navCollapsed?'nav-collapsed':''}"><aside class="sidebar"><button class="brand plain" id="brand">${icon('wrench',25)}<span><b>${t('brand')}</b><small>ENGEDNY</small></span></button><nav>${nav.map(([v,i])=>`<button class="nav ${S.view===v?'active':''}" data-nav="${v}">${icon(i)}<span>${v==='profile'?(rtl()?'البروفايل':'Profile'):t(v)}</span></button>`).join('')}</nav><button class="logout" id="logout">${icon('arrow')} ${t('logout')}</button></aside><section class="content">${S.navCollapsed?`<button id="showNav" class="mobile-nav-back" aria-label="${t('back')}">${icon('arrow',20)}<span>${t('back')}</span></button>`:''}${content}</section></main>`}
function role(){return `<div class="onboard"><div class="onboard-card clay"><button class="language" id="language">${S.lang==='ar'?'EN':'ع'}</button><div class="logo">${icon('wrench',34)}</div><h1>${t('brand')}</h1><p>${t('tag')}</p><h2>${t('choose')}</h2><div class="role-grid"><button class="role clay" data-role="customer">${icon('user',35)}<b>${t('customer')}</b><small>${t('customerDesc')}</small></button><button class="role clay" data-role="provider">${icon('wrench',35)}<b>${t('provider')}</b><small>${t('providerDesc')}</small></button></div><p class="tiny">${t('login')}${rtl()?'؟':'?'} <button id="login" class="text-btn">${t('login')}</button></p></div></div>`}
function auth(services){const provider=S.role==='provider';return `<div class="onboard"><form id="auth" class="auth clay"><button type="button" id="back" class="back">${icon('arrow')} ${t('back')}</button><button type="button" class="language" id="language">${S.lang==='ar'?'EN':'ع'}</button><div class="logo">${icon('wrench',34)}</div><h1>${S.login?t('login'):t('signup')}</h1>${!S.login?`<label>${t('name')}<input name="fullName" required></label><label>${t('phone')}<input name="phone" inputmode="tel" required></label><label class="file-field">${t('accountPhoto')} <input name="avatar" type="file" accept="image/png,image/jpeg,image/webp"><small>${t('optionalUpload')}</small></label>`:''}<label>${t('email')}<input name="email" type="email" required></label><label>${t('password')}<input name="password" type="password" minlength="8" required></label>${!S.login?`<label>${t('confirm')}<input name="confirmPassword" type="password" minlength="8" required></label>`:''}${provider&&!S.login?`<label>${t('service')}<select name="serviceId" required><option value="">${t('service')}</option>${services.map(x=>`<option value="${x.id}">${esc(rtl()?x.name_ar:x.name_en)}</option>`).join('')}</select></label><div class="form-row"><label>${t('city')}<input name="location" required></label><label>${t('experience')}<input name="experience" type="number" min="0" value="0" required></label></div><label>${t('bio')}<textarea name="bio"></textarea></label>`:''}<button class="primary">${S.login?t('login'):t('signup')}</button><p class="tiny"><button type="button" id="switch" class="text-btn">${S.login?t('signup'):t('login')}</button></p><div class="error" id="error"></div></form></div>`}
function statusText(s){return ({Pending:t('pending'),Accepted:t('accepted'),Rejected:t('rejected'),'On the way':t('onway'),'In Progress':t('progress'),Completed:t('completed'),Cancelled:t('cancelled')})[s]||s}
function providerRow(p){const portrait=p.avatar_data?`<img src="${p.avatar_data}" alt="${esc(p.full_name)}">`:serviceIcon(p.name_en),saved=!!S.data?.favorites?.includes(p.id);return `<article class="provider clay"><div class="provider-photo">${portrait}</div><div class="provider-info"><b>${esc(p.full_name)}</b><span>${esc(rtl()?p.name_ar:p.name_en)} · ${esc(p.location)} · ${p.experience} ${t('experience')}</span><em>${icon('star',14)} ${Number(p.rating).toFixed(1)} · ${p.review_count||0} ${t('reviews')}</em></div>${S.user?.role==='customer'?`<button class="favorite ${saved?'saved':''}" data-favorite="${p.id}" aria-label="${saved?'إزالة من المفضلة':'إضافة إلى المفضلة'}" aria-pressed="${saved}">${icon('heart',18)}</button><button class="ghost" data-message="${p.user_id}" data-message-name="${esc(p.full_name)}">${icon('chat',16)} ${t('messageProvider')}</button><button class="primary" data-provider="${p.id}">${t('book')}</button>`:''}</article>`}
function home(){const d=S.data;if(S.user.role==='provider'){const fans=d.favoriteCustomers||[];return shell(`<header class="welcome clay"><div><p>${t('newRequest')}</p><h1>${esc(d.user.full_name)}</h1><span>${d.requests.filter(x=>x.status==='Pending').length} ${t('pending')} · ${fans.length} ${t('favoritedMe')}</span></div><div class="hero-art">${serviceIcon('General Maintenance')}</div></header>${fans.length?`<section class="favorite-customers"><div class="section-head"><h2>${t('favoritedMe')}</h2><span>${fans.length}</span></div><div class="request-list">${fans.map(c=>`<article class="notice clay favorite-customer"><div class="avatar">${c.avatar_data?`<img src="${c.avatar_data}" alt="${esc(c.full_name)}">`:icon('user',22)}</div><div><b>${esc(c.full_name)}</b><span>${t('favoriteCustomerText')}</span></div><button class="ghost small" data-message="${c.id}" data-message-name="${esc(c.full_name)}">${icon('chat',15)} ${t('messageProvider')}</button></article>`).join('')}</div></section>`:''}<div class="section-head"><h2>${t('orders')}</h2></div>${requestList(d.requests,true)}`)}return shell(`<header class="welcome clay"><div><p>${t('tag')}</p><h1>${esc(d.user.full_name.split(' ')[0])}</h1><span>${t('search')}</span></div><div class="hero-art">${serviceIcon('General Maintenance')}</div></header><label class="search clay">${icon('search',20)}<input id="search" autocomplete="off" placeholder="${t('search')}"></label><section id="searchResults" class="search-results" hidden><div id="matchedService"></div><div class="section-head results-title"><h2>${t('providers')}</h2><span id="searchCount">0</span></div><div id="instantProviders" class="provider-list"></div></section><section id="browseServices"><div class="section-head"><h2>${t('services')}</h2><span>${d.services.length}</span></div><div class="services">${d.services.map(x=>`<button class="service clay" data-service="${esc(x.name_en)}">${serviceIcon(x.name_en)}<span>${esc(rtl()?x.name_ar:x.name_en)}</span></button>`).join('')}</div><div class="section-head"><h2>${t('providers')}</h2><span id="count">${S.providers.length}</span></div><div id="providers" class="provider-list">${S.providers.map(providerRow).join('')}</div></section>`)}
function requestList(items,providerMode=false){if(!items.length)return `<div class="empty clay">${t('noOrders')}</div>`;return `<div class="request-list">${items.map(r=>`<article class="request clay"><div><b>${esc(rtl()?r.name_ar:r.name_en||r.name_ar)}</b><span>${esc(providerMode?r.customer_name:r.provider_name||'')} · ${r.date} ${r.time}</span><small>${esc(r.location)} · ${statusText(r.status)}</small></div><div class="request-actions">${providerMode&&r.status==='Pending'?`<button class="primary small" data-status="${r.id}:Accepted">${icon('check',15)} ${t('accept')}</button><button class="danger small" data-status="${r.id}:Rejected">${t('reject')}</button>`:''}${providerMode&&r.status==='Accepted'?`<button class="ghost small" data-status="${r.id}:On the way">${t('onway')}</button>`:''}${providerMode&&r.status==='On the way'?`<button class="ghost small" data-status="${r.id}:In Progress">${t('progress')}</button>`:''}${providerMode&&r.status==='In Progress'?`<button class="primary small" data-status="${r.id}:Completed">${t('complete')}</button>`:''}<button class="ghost small" data-track="${r.id}">${t('track')}</button>${!providerMode&&r.status==='Completed'?(r.payment_id?`<span class="status">${esc(r.payment_status)}</span>`:`<button class="primary small" data-pay="${r.id}">${t('payment')}</button>`)+`<button class="primary small" data-rate="${r.id}">${t('rate')}</button>`:''}</div></article>`).join('')}</div>`}
function booking(){const p=S.chosen, today=new Date().toISOString().slice(0,10);return shell(`<button id="back" class="back">${icon('arrow')} ${t('back')}</button><form id="booking" class="form clay"><div class="provider-heading"><div class="avatar">${serviceIcon()}</div><div><h1>${t('book')}</h1><p>${esc(p.full_name)} · ${esc(rtl()?p.name_ar:p.name_en)}</p></div></div><label>${t('description')}<textarea name="description" required></textarea></label><label>${t('location')}<input name="location" required></label><div class="form-row"><label>${t('date')}<input name="date" type="date" value="${today}" required></label><label>${t('time')}<input name="time" type="time" value="10:00" required></label></div><p class="muted">${t('paymentAfter')}</p><button class="primary">${t('send')}</button><div class="error" id="error"></div></form>`)}
function ordersPage(){return shell(`<div class="page-title"><h1>${t('orders')}</h1></div>${requestList(S.data.requests,S.user.role==='provider')}`)}
function localizedNotice(text){const map={'طلب خدمة جديد':t('newServiceRequest'),'لديك طلب جديد يحتاج إلى ردك.':t('newRequestInfo')};return map[text]||text}
async function notificationsPage(){const notes=await api.notifications(S.user.id);return shell(`<div class="page-title"><h1>${t('notifications')}</h1></div><div class="request-list">${notes.length?notes.map(n=>`<article class="notice clay ${n.source_user_id?'clickable':''}" ${n.source_user_id?`data-note-peer="${n.source_user_id}"`:''}>${icon('bell',20)}<div><b>${esc(localizedNotice(n.title))}</b><span>${esc(localizedNotice(n.body))}</span><small>${esc(n.created_at)}</small></div></article>`).join(''):`<div class="empty clay">${t('noNotifications')}</div>`}</div>`)}
function peers(){return S.chatPeers||[]}
function messageStatus(m){if(m.read_at)return `<span class="delivery read">✓✓ ${t('seenStatus')}</span>`;if(m.delivered_at)return `<span class="delivery delivered">✓✓ ${t('deliveredStatus')}</span>`;return `<span class="delivery sent">✓ ${t('sentStatus')}</span>`}
function attachmentMarkup(m){if(!m.attachment_data)return '';const isImage=(m.attachment_mime||'').startsWith('image/'),name=esc(m.attachment_name||'attachment');return isImage?`<a class="chat-attachment image-attachment" href="${m.attachment_data}" download="${name}" aria-label="${t('fileAttached')}: ${name}"><img src="${m.attachment_data}" alt="${name}"><small>${name}</small></a>`:`<a class="chat-attachment file-attachment" href="${m.attachment_data}" download="${name}"><span class="file-mark">FILE</span><span><b>${name}</b><small>${esc(m.attachment_mime||'file')}</small></span></a>`}
function messagesMarkup(msgs){return msgs.map(m=>`<div class="bubble ${m.sender_id===S.user.id?'mine':''}">${m.body?`<span>${esc(m.body)}</span>`:''}${attachmentMarkup(m)}${m.sender_id===S.user.id?messageStatus(m):''}</div>`).join('')||`<p class="muted">${t('startChat')}</p>`}
function messageSignature(msgs){return msgs.map(m=>`${m.id}:${m.delivered_at||''}:${m.read_at||''}:${m.body}:${m.attachment_name||''}`).join('|')}
async function refreshChat(){if(!S.user||S.view!=='chat'||!S.chatPeer)return;try{const msgs=await api.messages(S.user.id,S.chatPeer.id);const box=$('#messages');if(!box)return;const sig=messageSignature(msgs);if(box.dataset.signature===sig)return;box.innerHTML=messagesMarkup(msgs);box.dataset.signature=sig;box.scrollTop=box.scrollHeight}catch{}}
function openMessageNotification(note){if(note.source_user_id){S.chatPeer={id:+note.source_user_id};S.view='chat'}else S.view='notifications';draw()}
function showToast(note){const toast=document.createElement('button');toast.type='button';toast.className='app-toast';toast.innerHTML=`${icon('bell',18)}<span><b>${esc(note.title)}</b><small>${esc(note.body)}</small></span>`;toast.onclick=()=>{toast.remove();openMessageNotification(note)};document.body.append(toast);setTimeout(()=>toast.remove(),6000);if('Notification'in window&&Notification.permission==='granted'&&document.hidden)new Notification(note.title,{body:note.body})}
async function syncNotifications(){if(!S.user)return;try{const notes=await api.notifications(S.user.id),latest=notes[0]?.id||0;if(!notificationsReady){lastNotificationId=latest;notificationsReady=true;return}const fresh=notes.filter(n=>n.id>lastNotificationId).sort((a,b)=>a.id-b.id);if(fresh.length){fresh.forEach(showToast);if(S.user.role==='customer'&&fresh.some(n=>n.title==='تحديث الطلب'||n.title==='فاتورة جديدة')){S.data=null;if(S.view==='orders'||S.view==='invoices')draw()}}lastNotificationId=Math.max(lastNotificationId,latest)}catch{}}
async function pulse(){if(!S.user)return;try{await api.presence(S.user.id)}catch{}await refreshChat();await syncNotifications()}
function startLive(){if(liveTimer)return;pulse();liveTimer=setInterval(pulse,2500)}
function stopLive(){if(liveTimer)clearInterval(liveTimer);liveTimer=0}
async function chatPage(){const pp=await api.chatPeers(S.user.id);S.chatPeers=pp;if(S.chatPeer)S.chatPeer=pp.find(p=>p.id===S.chatPeer.id)||null;if(!S.chatPeer&&pp[0])S.chatPeer=pp[0];const msgs=S.chatPeer?await api.messages(S.user.id,S.chatPeer.id):[],sig=messageSignature(msgs);return shell(`<div class="chat-layout"><aside class="peer-list clay"><h2>${t('chat')}</h2>${pp.length?pp.map(p=>`<button class="peer ${S.chatPeer?.id===p.id?'selected':''}" data-peer="${p.id}">${icon('user',18)} ${esc(p.full_name)}</button>`).join(''):`<p class="muted">${t('createOtherAccount')}</p>`}</aside><section class="chat-box clay"><h1>${S.chatPeer?esc(S.chatPeer.full_name):t('chat')}</h1><div id="messages" class="messages" data-signature="${esc(sig)}">${messagesMarkup(msgs)}</div>${S.chatPeer?`<form id="messageForm" class="message-form"><label class="attach-control" title="${t('attachHint')}"><span>+</span><input id="chatAttachment" type="file" accept="*/*" aria-label="${t('attach')}"></label><input name="body" placeholder="${t('message')}"><button class="primary">${t('sendMessage')}</button></form><p id="attachmentName" class="attachment-name">${t('attachHint')}</p><div class="error chat-error" id="chatError"></div>`:''}</section></div>`)}
function profile(){const u=S.data.user,p=S.data.profile,portrait=u.avatar_data?`<img src="${u.avatar_data}" alt="${esc(u.full_name)}">`:icon('user',38),roleLabel=S.user.role==='provider'?t('roleProvider'):t('roleCustomer');return shell(`<div class="page-title"><h1>${t('profile')}</h1><p>${roleLabel} · ${t('manageAccount')}</p></div><div class="profile-grid profile-layout"><section class="profile-card clay profile-identity"><div class="profile-cover"></div><div class="avatar big user-avatar">${portrait}</div><div class="identity-copy"><h2>${esc(u.full_name)}</h2><span class="role-chip">${icon(S.user.role==='provider'?'wrench':'user',14)} ${roleLabel}</span><p class="contact-line">${esc(u.email)}<i></i>${esc(u.phone)}</p></div><label class="profile-upload"><span>${icon('user',17)} ${t('changePhoto')}</span><small>${t('uploadPhotoHint')}</small><input id="avatarUpload" type="file" accept="image/png,image/jpeg,image/webp"></label>${p?`<div class="provider-summary"><span>${icon('home',17)} ${esc(p.location)}</span><span>${icon('star',17)} ${p.experience} ${t('experience')}</span></div><p class="profile-bio">${esc(p.bio||t('profileBio'))}</p>`:''}</section><section class="profile-card clay profile-details"><article class="profile-detail"><i>${icon('home',21)}</i><div><b>${t('address')}</b><span>${p?esc(p.location):t('customerLocation')}</span></div></article><article class="profile-detail"><i>${icon('credit',21)}</i><div><b>${t('payment')}</b><span>${t('cash')} · ${t('card')} · ${t('wallet')}</span></div></article><article class="profile-detail"><i>${icon('support',21)}</i><div><b>${t('support')}</b><span>support@engedny.local</span></div></article></section></div>`)}
function settings(){const saved=S.user.role==='customer'?S.data.providers.filter(p=>S.data.favorites?.includes(p.id)):[];const darkLabel=S.lang==='ar'?'الوضع الداكن':'Dark mode';return shell(`<div class="page-title"><h1>${t('settings')}</h1></div><section class="settings clay"><label>${t('language')}<select id="langSelect"><option value="ar" ${S.lang==='ar'?'selected':''}>${t('arabic')}</option><option value="en" ${S.lang==='en'?'selected':''}>${t('english')}</option></select></label><label class="theme-row"><span>${darkLabel}</span><input id="themeToggle" class="theme-switch" type="checkbox" ${S.theme==='dark'?'checked':''}></label><div><h2>${t('favorites')}</h2><p>${saved.length} ${t('savedProviders')}</p>${saved.length?`<div class="provider-list">${saved.map(providerRow).join('')}</div>`:`<p class="muted">${t('addFavoriteHint')}</p>`}</div><div><h2>${t('support')}</h2><p>support@engedny.local</p></div></section>`)}
function tracker(id){const r=S.data.requests.find(x=>x.id===+id);const steps=['Pending','Accepted','On the way','In Progress','Completed'], current=Math.max(0,steps.indexOf(r.status));return `<div class="modal-wrap"><section class="modal clay"><button class="close" id="close">×</button><h1>${t('track')}</h1><p>${esc(r.name_ar)} · ${esc(r.location)}</p><div class="timeline">${steps.map((s,i)=>`<div class="step ${i<=current?'done':''}"><i>${i<=current?icon('check',15):''}</i><span>${statusText(s)}</span></div>`).join('')}</div></section></div>`}
function rating(id){const r=S.data.requests.find(x=>x.id===+id);return `<div class="modal-wrap"><form id="rateForm" class="modal clay"><button type="button" class="close" id="close">×</button><h1>${t('rateProvider')}</h1><p>${t('rateDescription')} ${esc(r.provider_name||t('roleProvider'))}.</p><input type="hidden" name="requestId" value="${r.id}"><div class="stars" aria-label="${t('rate')}">${[1,2,3,4,5].map(n=>`<button type="button" class="chosen" data-star="${n}" aria-label="${n}">${icon('star',29)}</button>`).join('')}</div><input type="hidden" name="rating" value="5"><label>${t('reviews')}<textarea name="body" placeholder="${t('reviewOptional')}"></textarea></label><button class="primary">${t('sendRating')}</button></form></div>`}
function paymentModal(id){return `<div class="modal-wrap"><form id="paymentForm" class="modal clay"><button type="button" class="close" id="paymentClose">×</button><h1>${t('payment')}</h1><p>${t('paymentAfterComplete')}</p><input type="hidden" name="requestId" value="${id}"><label>${t('payment')}<select name="method"><option value="Cash">${t('cash')}</option><option value="Card">${t('card')}</option><option value="Wallet">${t('wallet')}</option></select></label><button class="primary">${t('confirmPayment')}</button><div class="error" id="paymentError"></div></form></div>`}
function scrollChatToLatest(){const box=$('#messages');if(box)requestAnimationFrame(()=>{box.scrollTop=box.scrollHeight})}
async function draw(){setLang();if(S.user)startLive();if(S.view==='role'){$('#app').innerHTML=role();return bindRole()}if(S.view==='auth'){$('#app').innerHTML=auth(await api.services());return bindAuth()}if(!S.data){try{S.data=await api.data(S.user.id);S.providers=S.data.providers;if(S.user.role==='provider')S.customers=(await api.users('customer')).filter(x=>x.id!==S.user.id).map(x=>({id:x.id,name:x.full_name}))}catch(err){stopLive();notificationsReady=false;lastNotificationId=0;localStorage.removeItem('engedny-user');S={user:null,role:null,login:false,view:'role',data:null,providers:[],chosen:null,chatPeer:null,lang:S.lang};return draw()}}let html=S.view==='book'?booking():S.view==='orders'?ordersPage():S.view==='chat'?await chatPage():S.view==='notifications'?await notificationsPage():S.view==='profile'?profile():S.view==='settings'?settings():home();$('#app').innerHTML=html;bindApp();if(S.view==='chat')scrollChatToLatest()}
function toggleLang(){S.lang=S.lang==='ar'?'en':'ar';draw()}
function bindRole(){$('#language').onclick=toggleLang;document.querySelectorAll('[data-role]').forEach(x=>x.onclick=()=>{S.role=x.dataset.role;S.login=false;S.view='auth';draw()});$('#login').onclick=()=>{S.role='customer';S.login=true;S.view='auth';draw()}}
function bindAuth(){$('#language').onclick=toggleLang;$('#back').onclick=()=>{S.view='role';draw()};$('#switch').onclick=()=>{S.login=!S.login;draw()};$('#auth').onsubmit=async e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target)),avatarData=S.login?null:await fileData(e.target.avatar.files[0]);delete f.avatar;const r=S.login?await api.login(f):await api.signup({...f,avatarData,role:S.role,serviceId:+f.serviceId||null});S.user=r.user;localStorage.setItem('engedny-user',JSON.stringify(r.user));S.data=null;S.view='home';draw()}catch(err){$('#error').textContent=err.message}}}
function bindApp(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{const target=b.dataset.nav;if(S.view===target&&(target==='home'||target==='chat'))S.navCollapsed=!S.navCollapsed;else{S.view=target;S.navCollapsed=target==='home'||target==='chat'}draw()});$('#brand').onclick=()=>{S.view='home';S.navCollapsed=true;draw()};$('#logout').onclick=()=>{stopLive();notificationsReady=false;lastNotificationId=0;localStorage.removeItem('engedny-user');S={user:null,role:null,login:false,view:'role',data:null,providers:[],chosen:null,lang:S.lang};draw()};$('#langSelect')?.addEventListener('change',e=>{S.lang=e.target.value;draw()});$('#search')?.addEventListener('input',async e=>{const term=e.target.value.trim(), results=$('#searchResults'), browse=$('#browseServices');if(!term){results.hidden=true;browse.hidden=false;return}results.hidden=false;browse.hidden=true;S.providers=await api.providers(term);$('#instantProviders').innerHTML=S.providers.length?S.providers.map(providerRow).join(''):`<div class="empty clay">${t('noOrders')}</div>`;$('#searchCount').textContent=S.providers.length;bindApp()});document.querySelectorAll('[data-service]').forEach(b=>b.onclick=async()=>{const query=b.dataset.service;S.providers=await api.providers(query);$('#search').value=rtl()?b.textContent.trim():query;$('#search').dispatchEvent(new Event('input'))});document.querySelectorAll('[data-provider]').forEach(b=>b.onclick=()=>{S.chosen=S.providers.find(p=>p.id===+b.dataset.provider);S.view='book';S.navCollapsed=false;draw()});document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=async()=>{await api.favorite(+b.dataset.favorite,S.user.id);S.data=null;draw()});$('#back')?.addEventListener('click',()=>{S.view='home';S.navCollapsed=true;draw()});$('#booking')?.addEventListener('submit',async e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target));await api.booking({...f,userId:S.user.id,providerId:S.chosen.id,serviceId:S.chosen.service_id,price:0});S.data=null;S.view='orders';S.navCollapsed=false;draw()}catch(err){$('#error').textContent=err.message}});document.querySelectorAll('[data-status]').forEach(b=>b.onclick=async()=>{const [id,status]=b.dataset.status.split(':');await api.status(id,status);S.data=null;draw()});document.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>{$('#app').insertAdjacentHTML('beforeend',tracker(b.dataset.track));bindModal()});document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>{$('#app').insertAdjacentHTML('beforeend',rating(b.dataset.rate));bindModal()});document.querySelectorAll('[data-pay]').forEach(b=>b.onclick=()=>{$('#app').insertAdjacentHTML('beforeend',paymentModal(b.dataset.pay))});document.querySelectorAll('[data-peer]').forEach(b=>b.onclick=()=>{S.chatPeer=peers().find(p=>p.id===+b.dataset.peer);draw()});document.querySelectorAll('[data-note-peer]').forEach(n=>n.onclick=()=>openMessageNotification({source_user_id:n.dataset.notePeer}));$('#messageForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),error=$('#chatError');try{const attachment=await chatFileData($('#chatAttachment')?.files[0]);if(!String(f.body||'').trim()&&!attachment)throw Error(t('messageOrFile'));await api.message({senderId:S.user.id,receiverId:S.chatPeer.id,body:f.body||'',attachment});draw()}catch(err){if(error)error.textContent=err.message}})}
function bindModal(){$('#close').onclick=()=>$('.modal-wrap').remove();document.querySelectorAll('[data-star]').forEach(b=>b.onclick=()=>{$('#rateForm [name=rating]').value=b.dataset.star;document.querySelectorAll('[data-star]').forEach(x=>x.classList.toggle('chosen',+x.dataset.star<=+b.dataset.star))});$('#rateForm')?.addEventListener('submit',async e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target)),r=S.data.requests.find(x=>x.id===+f.requestId);await api.review({requestId:+f.requestId,customerId:S.user.id,providerId:r.provider_id,rating:+f.rating,body:f.body});$('.modal-wrap').remove();S.data=null;S.view='orders';draw()}catch(err){alert(err.message)}})}
document.addEventListener('input',e=>{if(e.target?.id!=='search'||!S.data)return;const query=e.target.value.trim();if(!query){S.providers=S.data.providers;return}const normalized=query.toLowerCase();const service=S.data.services.find(x=>x.name_en.toLowerCase().includes(normalized)||x.name_ar.includes(query));const slot=$('#matchedService');if(slot)slot.innerHTML=service?`<article class="matched-service clay">${serviceIcon()}<div><small>${t('matchedService')}</small><b>${esc(rtl()?service.name_ar:service.name_en)}</b><span>${t('chooseProviderResults')}</span></div></article>`:`<article class="matched-service clay">${icon('search',22)}<div><small>${t('searchResults')}</small><b>${esc(query)}</b><span>${t('providersBelow')}</span></div></article>`},true);
document.addEventListener('change',async e=>{if(e.target?.id==='themeToggle'){S.theme=e.target.checked?'dark':'light';draw();return}if(e.target?.id==='chatAttachment'){const file=e.target.files?.[0],name=$('#attachmentName'),error=$('#chatError');if(error)error.textContent='';if(!file){if(name)name.textContent=t('attachHint');return}if(file.type?.startsWith('video/')){e.target.value='';if(name)name.textContent=t('attachHint');if(error)error.textContent=t('videoNotAllowed');return}if(file.size>4000000){e.target.value='';if(name)name.textContent=t('attachHint');if(error)error.textContent=t('fileTooLarge');return}if(name)name.textContent=`${t('fileAttached')}: ${file.name}`;return}if(e.target?.id!=='avatarUpload')return;try{const avatarData=await fileData(e.target.files[0]);if(!avatarData)return;const r=await api.avatar(S.user.id,avatarData);S.user=r.user;localStorage.setItem('engedny-user',JSON.stringify(r.user));S.data=null;draw()}catch(err){alert(err.message)}},true);
document.addEventListener('submit',async e=>{if(e.target?.id!=='paymentForm')return;e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target));await api.payment({requestId:+f.requestId,method:f.method});$('.modal-wrap')?.remove();S.data=null;S.view='orders';draw()}catch(err){$('#paymentError').textContent=err.message}},true);
document.addEventListener('click',e=>{const button=e.target.closest?.('[data-message]');if(!button)return;S.chatPeer={id:+button.dataset.message,name:button.dataset.messageName};S.view='chat';draw()});
document.addEventListener('click',e=>{const button=e.target.closest?.('[data-nav]');if(!button||!S.user)return;e.preventDefault();e.stopImmediatePropagation();const target=button.dataset.nav;S.view=target;S.navCollapsed=true;draw()},true);
document.addEventListener('click',e=>{if(!e.target.closest?.('#showNav')||!S.user)return;e.preventDefault();e.stopImmediatePropagation();S.view='services';S.navCollapsed=false;draw()},true);
document.addEventListener('click',e=>{if(!e.target.closest?.('#showNav'))return;e.preventDefault();S.navCollapsed=false;draw()},true);
document.addEventListener('click',e=>{if(e.target?.id==='paymentClose')$('.modal-wrap')?.remove()});
/* Consolidated home with a dedicated service-selection page. */
function shell(content){const nav=[['home','home'],['services','search'],['orders','orders'],['chat','chat'],['notifications','bell'],['profile','user'],['settings','settings']];return `<main class="shell view-${S.view} ${S.navCollapsed?'nav-collapsed':''}"><aside class="sidebar"><button class="brand plain" id="brand">${icon('wrench',25)}<span><b>${t('brand')}</b><small>ENGEDNY</small></span></button><nav>${nav.map(([v,i])=>`<button class="nav ${S.view===v?'active':''}" data-nav="${v}">${icon(i)}<span>${v==='profile'?(rtl()?'البروفايل':'Profile'):t(v)}</span></button>`).join('')}</nav><button class="logout" id="logout">${icon('arrow')} ${t('logout')}</button></aside><section class="content">${S.navCollapsed?`<button id="showNav" class="mobile-nav-back" aria-label="${t('back')}">${icon('arrow',20)}<span>${t('back')}</span></button>`:''}${content}</section></main>`}
function home(){const d=S.data,name=esc(d.user.full_name),choose=rtl()?'اختاري خدمتك الآن':'Choose your service';return shell(`<header class="welcome clay"><div class="welcome-copy"><p>Welcome to Engedny</p><h1>${name}</h1>${S.user.role==='customer'?`<p><button class="primary" data-nav="services">${icon('search',17)} ${choose}</button></p>`:''}</div><div class="hero-art home-welcome-icon"><img src="/assets/engedny-mark.png?v=1" alt="${t('brand')}"></div></header>`)}
function servicesPage(){const d=S.data;return shell(`<div class="page-title"><h1>${rtl()?'اختاري الخدمة المناسبة':'Choose a service'}</h1><p>${rtl()?'ابحثي أو اختاري الخدمة ثم شاهدي مقدمي الخدمة المتاحين':'Search or choose a service, then view available providers.'}</p></div><label class="search clay">${icon('search',20)}<input id="search" autocomplete="off" placeholder="${t('search')}"></label><section id="searchResults" class="search-results" hidden><div id="matchedService"></div><div class="section-head results-title"><h2>${t('providers')}</h2><span id="searchCount">0</span></div><div id="instantProviders" class="provider-list"></div></section><section id="browseServices"><div class="section-head"><h2>${t('services')}</h2><span>${d.services.length}</span></div><div class="services">${d.services.map(x=>`<button class="service clay" data-service="${esc(x.name_en)}">${serviceIcon(x.name_en)}<span>${esc(rtl()?x.name_ar:x.name_en)}</span></button>`).join('')}</div><div class="section-head"><h2>${t('providers')}</h2><span id="count">${S.providers.length}</span></div><div id="providers" class="provider-list">${S.providers.map(providerRow).join('')}</div></section>`)}
function invoiceIcon(size=19){return `<svg class="ico" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M6 2h9l4 4v16H6z M15 2v5h5 M9 11h6 M9 15h6 M9 19h4"/></svg>`}
const invoiceMoney=n=>`${Number(n||0).toFixed(2)} ${rtl()?'ج.م':'EGP'}`;
const invoicePaymentLabel=m=>m==='Cash'?t('cash'):m==='Card'?t('card'):t('wallet');
function invoiceCard(i){const provider=S.user.role==='provider',paid=i.payment_status!=='Pending',net=Number(i.total_amount)-Number(i.platform_fee);const action=provider?(paid?(i.commission_status==='Pending'?`<div class="invoice-actions"><b>${t('commissionPending')}: ${invoiceMoney(i.platform_fee)}</b><button class="ghost small" data-commission="${i.id}:InstaPay">${t('instapay')}</button><button class="ghost small" data-commission="${i.id}:Wallet">${t('wallet')}</button></div>`:`<span class="invoice-success">${icon('check',15)} ${t('commissionDone')}</span>`):`<span class="status">${t('paymentPending')}</span>`):paid?`<span class="invoice-success">${icon('check',15)} ${esc(i.payment_status)}</span>`:`<button class="primary small" data-invoice-pay="${i.id}:${i.payment_method}">${t('payNow')}</button>`;return `<article class="invoice-card clay"><div class="invoice-title"><i>${invoiceIcon(22)}</i><div><b>${esc(rtl()?i.name_ar:i.name_en||t('invoices'))}</b><span>${esc(provider?i.customer_name:i.provider_name||'')} · ${i.date||''}</span></div><strong>${invoiceMoney(i.total_amount)}</strong></div><div class="invoice-lines"><p><b>${t('workDone')}</b><span>${esc(i.work_done)}</span></p>${i.materials?`<p><b>${t('materials')}</b><span>${esc(i.materials)}</span></p>`:''}</div><div class="invoice-summary"><span>${t('laborAmount')}<b>${invoiceMoney(i.labor_amount)}</b></span><span>${t('materialsAmount')}<b>${invoiceMoney(i.materials_amount)}</b></span><span>${t('platformCommission')}<b>${invoiceMoney(i.platform_fee)}</b></span>${provider?`<span>${t('technicianShare')}<b>${invoiceMoney(net)}</b></span>`:''}</div><div class="invoice-footer"><small>${t('paymentChoice')}: ${invoicePaymentLabel(i.payment_method)}</small>${action}</div></article>`}
function invoicesPage(){const d=S.data,provider=S.user.role==='provider',invoices=d.invoices||[],issued=new Set(invoices.map(x=>x.request_id)),eligible=(d.requests||[]).filter(r=>r.status==='Completed'&&!issued.has(r.id));const create=provider&&eligible.length?`<form id="invoiceForm" class="form clay invoice-form"><div class="page-title"><h2>${invoiceIcon(22)} ${t('createInvoice')}</h2><p>${t('demoPaymentNote')}</p></div><label>${t('completedRequest')}<select name="requestId" required>${eligible.map(r=>`<option value="${r.id}">${esc(rtl()?r.name_ar:r.name_en)} · ${esc(r.customer_name)}</option>`).join('')}</select></label><label>${t('workDone')}<textarea name="workDone" required placeholder="${rtl()?'مثال: إصلاح تسريب وتركيب وصلة جديدة':'Example: repaired leak and fitted a new connector'}"></textarea></label><label>${t('materials')}<textarea name="materials" placeholder="${rtl()?'مثال: وصلة، محبس، شريط عزل':'Example: connector, valve, insulation tape'}"></textarea></label><div class="form-row"><label>${t('laborAmount')}<input name="laborAmount" type="number" min="0" step="0.01" required></label><label>${t('materialsAmount')}<input name="materialsAmount" type="number" min="0" step="0.01" value="0" required></label></div><label>${t('paymentChoice')}<select name="paymentMethod"><option value="Cash">${t('cash')}</option><option value="Card">${t('card')}</option><option value="Wallet">${t('wallet')}</option></select></label><button class="primary">${t('issueInvoice')}</button><div class="error" id="invoiceError"></div></form>`:'';return shell(`<div class="page-title"><h1>${invoiceIcon(25)} ${t('invoices')}</h1><p>${t('demoPaymentNote')}</p></div>${create}<section class="invoice-list">${invoices.length?invoices.map(invoiceCard).join(''):`<div class="empty clay">${t('noInvoices')}</div>`}</section>`)}
async function draw(){setLang();if(S.user)startLive();if(S.view==='role'){$('#app').innerHTML=role();return bindRole()}if(S.view==='auth'){$('#app').innerHTML=auth(await api.services());return bindAuth()}if(!S.data){try{S.data=await api.data(S.user.id);S.providers=S.data.providers;if(S.user.role==='provider')S.customers=(await api.users('customer')).filter(x=>x.id!==S.user.id).map(x=>({id:x.id,name:x.full_name}))}catch(err){stopLive();notificationsReady=false;lastNotificationId=0;localStorage.removeItem('engedny-user');S={user:null,role:null,login:false,view:'role',data:null,providers:[],chosen:null,chatPeer:null,lang:S.lang};return draw()}}let html=S.view==='book'?booking():S.view==='services'?servicesPage():S.view==='orders'?ordersPage():S.view==='invoices'?invoicesPage():S.view==='chat'?await chatPage():S.view==='notifications'?await notificationsPage():S.view==='profile'?profile():S.view==='settings'?settings():home();$('#app').innerHTML=html;bindApp();if(S.view==='chat')scrollChatToLatest()}
/* Services is the first and only landing view after sign-in; no Home item. */
function shell(content){const nav=[['services','search'],['orders','orders'],['chat','chat'],['notifications','bell'],['profile','user'],['settings','settings']];return `<main class="shell view-${S.view} ${S.navCollapsed?'nav-collapsed':''}"><aside class="sidebar"><button class="brand plain" id="brand">${icon('wrench',25)}<span><b>${t('brand')}</b><small>ENGEDNY</small></span></button><nav>${nav.map(([v,i])=>`<button class="nav ${S.view===v?'active':''}" data-nav="${v}">${icon(i)}<span>${v==='profile'?(rtl()?'البروفايل':'Profile'):t(v)}</span></button>`).join('')}</nav><button class="logout" id="logout">${icon('arrow')} ${t('logout')}</button></aside><section class="content">${S.navCollapsed?`<button id="showNav" class="mobile-nav-back" aria-label="${t('back')}">${icon('arrow',20)}<span>${t('back')}</span></button>`:''}${content}</section></main>`}
document.addEventListener('click',e=>{if(!e.target.closest?.('#back')||!S.user)return;e.preventDefault();e.stopImmediatePropagation();S.view='services';S.navCollapsed=true;draw()},true);
const decorateInvoiceCards=()=>{if(S.view!=='invoices'||!S.data)return;document.querySelectorAll('.invoice-card:not([data-parties])').forEach((card,index)=>{const i=(S.data.invoices||[])[index];if(!i)return;const provider=S.user.role==='provider',tech=i.provider_name||(provider?S.data.user.full_name:''),customer=i.customer_name||(!provider?S.data.user.full_name:'');card.dataset.parties='1';card.querySelector('.invoice-title')?.insertAdjacentHTML('afterend',`<div class="invoice-identities"><img src="/assets/engedny-mark.png?v=1" alt="${t('brand')}"><span><b>${rtl()?'الفني':'Technician'}</b>${esc(tech)}</span><span><b>${rtl()?'العميل':'Customer'}</b>${esc(customer)}</span><span><b>${rtl()?'التاريخ':'Date'}</b>${esc(i.date||i.created_at||'')}</span></div>`)});};new MutationObserver(decorateInvoiceCards).observe($('#app'),{childList:true,subtree:true});
if(S.user)S.view='services';draw();
function shell(content){const nav=[['services','search'],['orders','orders'],['invoices','invoice'],['chat','chat'],['notifications','bell'],['profile','user'],['settings','settings']];return `<main class="shell view-${S.view} ${S.navCollapsed?'nav-collapsed':''}"><aside class="sidebar"><button class="brand plain" id="brand" aria-label="${rtl()?'الرئيسية':'Home'}"><img class="brand-logo" src="/assets/engedny-mark.png?v=1" alt="${t('brand')}"></button><nav>${nav.map(([v,i])=>`<button class="nav ${S.view===v?'active':''}" data-nav="${v}">${i==='invoice'?invoiceIcon():icon(i)}<span>${v==='profile'?(rtl()?'البروفايل':'Profile'):t(v)}</span></button>`).join('')}</nav><button class="logout" id="logout">${icon('arrow')} ${t('logout')}</button></aside><section class="content">${S.navCollapsed?`<button id="showNav" class="mobile-nav-back" aria-label="${t('back')}">${icon('arrow',20)}<span>${t('back')}</span></button>`:''}${content}</section></main>`}
document.addEventListener('submit',async e=>{if(e.target?.id!=='invoiceForm')return;e.preventDefault();const error=$('#invoiceError');try{const f=Object.fromEntries(new FormData(e.target));await api.invoice({...f,providerId:S.user.id});S.data=null;draw()}catch(err){if(error)error.textContent=err.message}},true);
document.addEventListener('click',async e=>{const pay=e.target.closest?.('[data-invoice-pay]'),commission=e.target.closest?.('[data-commission]');if(!S.user||(!pay&&!commission))return;e.preventDefault();try{if(pay){const [id,method]=pay.dataset.invoicePay.split(':');await api.invoicePay(id,{userId:S.user.id,method})}else{const [id,method]=commission.dataset.commission.split(':');await api.commission(id,{providerId:S.user.id,method})}S.data=null;draw()}catch(err){alert(err.message)}},true);
function invoiceCard(i){const provider=S.user.role==='provider',paid=i.payment_status!=='Pending',net=Number(i.total_amount)-Number(i.platform_fee);const action=provider?(paid?(i.commission_status==='Pending'?`<div class="invoice-actions"><b>${t('commissionPending')}: ${invoiceMoney(i.platform_fee)}</b><button class="ghost small" data-commission="${i.id}:InstaPay">${t('instapay')}</button><button class="ghost small" data-commission="${i.id}:Wallet">${t('wallet')}</button></div>`:`<span class="invoice-success">${icon('check',15)} ${t('commissionDone')}</span>`):`<span class="status">${t('paymentPending')}</span>`):paid?`<span class="invoice-success">${icon('check',15)} ${esc(i.payment_status)}</span>`:`<button class="primary small" data-invoice-pay="${i.id}:${i.payment_method}">${t('payNow')}</button>`;return `<article class="invoice-card clay"><div class="invoice-title"><i>${invoiceIcon(22)}</i><div><b>${esc(rtl()?i.name_ar:i.name_en||t('invoices'))}</b><span>${esc(provider?i.customer_name:i.provider_name||'')} · ${i.date||''}</span></div><strong>${invoiceMoney(i.total_amount)}</strong></div><div class="invoice-lines"><p><b>${t('workDone')}</b><span>${esc(i.work_done)}</span></p>${i.materials?`<p><b>${t('materials')}</b><span>${esc(i.materials)}</span></p>`:''}</div><div class="invoice-summary"><span>${t('laborAmount')}<b>${invoiceMoney(i.labor_amount)}</b></span><span>${t('materialsAmount')}<b>${invoiceMoney(i.materials_amount)}</b></span><span>${t('platformCommission')}<b>${invoiceMoney(i.platform_fee)}</b></span>${provider?`<span>${t('technicianShare')}<b>${invoiceMoney(net)}</b></span>`:''}</div><div class="invoice-footer"><small>${t('paymentChoice')}: ${invoicePaymentLabel(i.payment_method)}</small><div class="invoice-actions"><button class="ghost small" data-export-invoice="${i.id}">${invoiceIcon(15)} ${t('exportInvoice')}</button>${action}</div></div></article>`}
function exportInvoice(id){const i=(S.data?.invoices||[]).find(x=>x.id===Number(id));if(!i)return;const w=window.open('','_blank');if(!w)return alert(rtl()?'اسمحي بفتح النافذة لتصدير الفاتورة.':'Allow pop-ups to export the invoice.');const provider=S.user.role==='provider',party=provider?i.customer_name:i.provider_name,dir=rtl()?'rtl':'ltr';w.document.write(`<!doctype html><html dir="${dir}"><head><meta charset="utf-8"><title>Engedny Invoice #${i.id}</title><style>body{font-family:Tahoma,Arial,sans-serif;margin:42px;color:#102a56}.head{display:flex;justify-content:space-between;align-items:center;border-bottom:3px solid #2563eb;padding-bottom:18px}.mark{font-size:25px;font-weight:800;color:#2563eb}.box{margin-top:24px;padding:20px;border:1px solid #dbeafe;border-radius:15px}p{line-height:1.65}table{width:100%;border-collapse:collapse;margin-top:18px}td,th{padding:12px;border-bottom:1px solid #dbeafe;text-align:start}.total{font-size:18px;font-weight:800;color:#2563eb}.note{margin-top:28px;color:#64748b;font-size:12px}@media print{body{margin:22px}}</style></head><body><div class="head"><div class="mark">انجدني | Engedny</div><div>Invoice #${i.id}</div></div><div class="box"><b>${esc(rtl()?'الطرف الآخر':'Service party')}: ${esc(party||'')}</b><p><b>${esc(t('workDone'))}:</b><br>${esc(i.work_done)}</p><p><b>${esc(t('materials'))}:</b><br>${esc(i.materials||'-')}</p><table><tr><th>${esc(t('laborAmount'))}</th><td>${invoiceMoney(i.labor_amount)}</td></tr><tr><th>${esc(t('materialsAmount'))}</th><td>${invoiceMoney(i.materials_amount)}</td></tr><tr><th>${esc(t('total'))}</th><td class="total">${invoiceMoney(i.total_amount)}</td></tr></table><p><b>${esc(t('paymentChoice'))}:</b> ${esc(invoicePaymentLabel(i.payment_method))}</p></div><p class="note">${esc(t('demoPaymentNote'))}</p><script>setTimeout(()=>print(),250)<\/script></body></html>`);w.document.close()}
document.addEventListener('click',e=>{const button=e.target.closest?.('[data-export-invoice]');if(!button)return;e.preventDefault();exportInvoice(button.dataset.exportInvoice)},true);
document.addEventListener('click',e=>{const card=e.target.closest?.('.view-invoices .invoice-card');if(!card||e.target.closest('button'))return;card.classList.toggle('invoice-open');card.setAttribute('aria-expanded',String(card.classList.contains('invoice-open')))},true);
document.addEventListener('click',e=>{const notice=e.target.closest?.('[data-note-peer]');if(!notice||!S.user)return;e.preventDefault();e.stopImmediatePropagation();openMessageNotification({source_user_id:notice.dataset.notePeer})},true);
function profile(){const u=S.data.user,p=S.data.profile,portrait=u.avatar_data?`<img src="${u.avatar_data}" alt="${esc(u.full_name)}">`:icon('user',38),roleLabel=S.user.role==='provider'?t('roleProvider'):t('roleCustomer'),removeLabel=rtl()?'حذف صورة الحساب':'Remove profile photo';return shell(`<div class="page-title"><h1>${t('profile')}</h1><p>${roleLabel} · ${t('manageAccount')}</p></div><div class="profile-grid profile-layout"><section class="profile-card clay profile-identity"><div class="profile-cover"></div><div class="avatar big user-avatar">${portrait}</div><div class="identity-copy"><h2>${esc(u.full_name)}</h2><span class="role-chip">${icon(S.user.role==='provider'?'wrench':'user',14)} ${roleLabel}</span><p class="contact-line">${esc(u.email)}<i></i>${esc(u.phone)}</p></div><label class="profile-upload"><span>${icon('user',17)} ${t('changePhoto')}</span><small>${t('uploadPhotoHint')}</small><input id="avatarUpload" type="file" accept="image/png,image/jpeg,image/webp"></label>${u.avatar_data?`<button type="button" class="remove-avatar" data-remove-avatar>× ${removeLabel}</button>`:''}${p?`<div class="provider-summary"><span>${icon('home',17)} ${esc(p.location)}</span><span>${icon('star',17)} ${p.experience} ${t('experience')}</span></div><p class="profile-bio">${esc(p.bio||t('profileBio'))}</p>`:''}</section><section class="profile-card clay profile-details"><article class="profile-detail"><i>${icon('home',21)}</i><div><b>${t('address')}</b><span>${p?esc(p.location):t('customerLocation')}</span></div></article><article class="profile-detail"><i>${icon('credit',21)}</i><div><b>${t('payment')}</b><span>${t('cash')} · ${t('card')} · ${t('wallet')}</span></div></article><article class="profile-detail"><i>${icon('support',21)}</i><div><b>${t('support')}</b><span>support@engedny.local</span></div></article></section></div>`) }
document.addEventListener('click',async e=>{if(!e.target.closest?.('[data-remove-avatar]')||!S.user)return;e.preventDefault();try{const result=await api.removeAvatar(S.user.id);S.user=result.user;localStorage.setItem('engedny-user',JSON.stringify(result.user));S.data=null;draw()}catch(err){alert(err.message)}},true);
function servicesPage(){const d=S.data,colors=['#f59e0b','#2479ef','#10a978','#8b5bd7','#3d9cff','#ef6a86','#64748b','#14b8a6'],labels={ar:{hello:'صباح الخير',title:'كيف نساعدك اليوم؟',subtitle:'ابحثي عن فني موثوق لخدمات منزلك',location:'القاهرة، مصر',map:'فنيون قريبون منك',popular:'الخدمات الأكثر طلبًا',top:'أفضل الفنيين بالقرب منك',all:'عرض الكل'},en:{hello:'Good morning',title:'How can we help today?',subtitle:'Find a trusted professional for your home',location:'Cairo, Egypt',map:'Professionals near you',popular:'Popular services',top:'Top professionals near you',all:'See all'}}[rtl()?'ar':'en'];const serviceTile=(x,i)=>`<button class="market-service" data-service="${esc(x.name_en)}" style="--service-accent:${colors[i%colors.length]}"><i>${serviceIcon(x.name_en)}</i><span>${esc(rtl()?x.name_ar:x.name_en)}</span></button>`;const pins=d.services.slice(0,5).map((x,i)=>`<button class="map-pin pin-${i+1}" data-service="${esc(x.name_en)}" style="--pin:${colors[i%colors.length]}" aria-label="${esc(rtl()?x.name_ar:x.name_en)}">${serviceIcon(x.name_en)}</button>`).join('');return shell(`<section class="market-home"><header class="market-head"><div><p>${labels.hello}</p><h1>${labels.title}</h1><span>${labels.subtitle}</span></div><button class="market-location">${icon('home',18)} ${labels.location}</button></header><label class="market-search">${icon('search',21)}<input id="search" autocomplete="off" placeholder="${t('search')}"><i>${icon('settings',18)}</i></label><section id="searchResults" class="search-results market-results" hidden><div id="matchedService"></div><div class="section-head results-title"><h2>${t('providers')}</h2><span id="searchCount">0</span></div><div id="instantProviders" class="provider-list"></div></section><section id="browseServices"><div class="service-map" aria-label="${labels.map}"><div class="map-grid"></div><span class="map-street street-a"></span><span class="map-street street-b"></span><span class="map-street street-c"></span><b>${labels.map}</b><span class="my-location"></span>${pins}</div><div class="market-section-title"><h2>${labels.popular}</h2><button type="button">${labels.all}</button></div><div class="market-services">${d.services.slice(0,8).map(serviceTile).join('')}</div><div class="market-section-title"><h2>${labels.top}</h2><button type="button">${labels.all}</button></div><div id="providers" class="provider-list market-providers">${S.providers.map(providerRow).join('')}</div></section></section>`) }
/* Each completed request follows one clear path: invoice, payment, then rating. */
function requestList(items,providerMode=false){if(!items.length)return `<div class="empty clay">${t('noOrders')}</div>`;const invoiceFor=id=>(S.data?.invoices||[]).find(i=>Number(i.request_id)===Number(id)),reviewFor=id=>(S.data?.reviews||[]).find(x=>Number(x.request_id)===Number(id));return `<div class="request-list">${items.map(r=>{let actions=`<button class="ghost small" data-track="${r.id}">${t('track')}</button>`;if(providerMode){if(r.status==='Pending')actions=`<button class="primary small" data-status="${r.id}:Accepted">${icon('check',15)} ${t('accept')}</button><button class="danger small" data-status="${r.id}:Rejected">${t('reject')}</button>`+actions;else if(r.status==='Accepted')actions=`<button class="ghost small" data-status="${r.id}:On the way">${t('onway')}</button>`+actions;else if(r.status==='On the way')actions=`<button class="ghost small" data-status="${r.id}:In Progress">${t('progress')}</button>`+actions;else if(r.status==='In Progress')actions=`<button class="primary small" data-status="${r.id}:Completed">${t('complete')}</button>`+actions}else if(r.status==='Completed'){const invoice=invoiceFor(r.id),review=reviewFor(r.id),paid=invoice?invoice.payment_status!=='Pending':!!r.payment_id;if(!invoice&&!r.payment_id)actions+=`<span class="status">${rtl()?'بانتظار إصدار الفاتورة':'Awaiting invoice'}</span>`;else if(!paid)actions+=`<button class="primary small" data-nav="invoices">${rtl()?'ادفع الفاتورة':'Pay invoice'}</button>`;else{actions+=`<span class="status">${rtl()?'تم الدفع':'Paid'}</span>`;actions+=review?`<span class="status">${rtl()?'تم تقييم الخدمة':'Service rated'} ★ ${review.rating}</span>`:`<button class="primary small" data-rate="${r.id}">${t('rate')}</button>`}}return `<article class="request clay"><div><b>${esc(rtl()?r.name_ar:r.name_en||r.name_ar)}</b><span>${esc(providerMode?r.customer_name:r.provider_name||'')} · ${r.date} ${r.time}</span><small>${esc(r.location)} · ${statusText(r.status)}</small></div><div class="request-actions">${actions}</div></article>`}).join('')}</div>`}
function servicesPage(){const d=S.data,colors=['#f59e0b','#2479ef','#10a978','#8b5bd7','#3d9cff','#ef6a86','#64748b','#14b8a6'],ar=rtl(),copy=ar?{hello:'صباح الخير',title:'كيف نساعدك اليوم؟',subtitle:'ابحثي عن فني موثوق لخدمات منزلك',location:'القاهرة، مصر',map:'فنيون قريبون منك',popular:'الخدمات الأكثر طلبًا',top:'أفضل الفنيين بالقرب منك',all:'عرض الكل',less:'عرض أقل',found:'الفنيون المتاحون لهذه الخدمة'}:{hello:'Good morning',title:'How can we help today?',subtitle:'Find a trusted professional for your home',location:'Cairo, Egypt',map:'Professionals near you',popular:'Popular services',top:'Top professionals near you',all:'See all',less:'Show less',found:'Available professionals'};const allServices=!!S.showAllServices,allProviders=!!S.showAllProviders,shownServices=(allServices?d.services:d.services.slice(0,8)),shownProviders=(allProviders?S.providers:S.providers.slice(0,4)),tile=(x,i)=>`<button class="market-service" data-service="${esc(x.name_en)}" style="--service-accent:${colors[i%colors.length]}"><i>${serviceIcon(x.name_en)}</i><span>${esc(ar?x.name_ar:x.name_en)}</span></button>`,pins=d.services.slice(0,5).map((x,i)=>`<button class="map-pin pin-${i+1}" data-map-service="${esc(x.name_en)}" style="--pin:${colors[i%colors.length]}" aria-label="${esc(ar?x.name_ar:x.name_en)}">${serviceIcon(x.name_en)}</button>`).join(''),mapResults=S.mapService?`<section class="map-provider-results"><div><b>${copy.found}</b><span>${esc(ar?(d.services.find(s=>s.name_en===S.mapService)?.name_ar||S.mapService):S.mapService)}</span></div><div class="provider-list market-providers">${S.providers.length?S.providers.map(providerRow).join(''):`<p class="muted">${t('noOrders')}</p>`}</div></section>`:'';return shell(`<section class="market-home"><header class="market-head"><div><p>${copy.hello}</p><h1>${copy.title}</h1><span>${copy.subtitle}</span></div><button class="market-location">${icon('home',18)} ${copy.location}</button></header><label class="market-search">${icon('search',21)}<input id="search" autocomplete="off" placeholder="${t('search')}"><i>${icon('settings',18)}</i></label><section id="searchResults" class="search-results market-results" hidden><div id="matchedService"></div><div class="section-head results-title"><h2>${t('providers')}</h2><span id="searchCount">0</span></div><div id="instantProviders" class="provider-list"></div></section><section id="browseServices"><div class="service-map" aria-label="${copy.map}"><div class="map-grid"></div><span class="map-street street-a"></span><span class="map-street street-b"></span><span class="map-street street-c"></span><b>${copy.map}</b><span class="my-location"></span>${pins}</div>${mapResults}<div class="market-section-title"><h2>${copy.popular}</h2><button type="button" data-market-toggle="services">${allServices?copy.less:copy.all}</button></div><div class="market-services">${shownServices.map(tile).join('')}</div><div class="market-section-title"><h2>${copy.top}</h2><button type="button" data-market-toggle="providers">${allProviders?copy.less:copy.all}</button></div><div id="providers" class="provider-list market-providers">${shownProviders.map(providerRow).join('')}</div></section></section>`) }
document.addEventListener('click',async e=>{const pin=e.target.closest?.('[data-map-service]'),toggle=e.target.closest?.('[data-market-toggle]');if(!S.user||(!pin&&!toggle))return;e.preventDefault();if(pin){S.mapService=pin.dataset.mapService;S.providers=await api.providers(S.mapService);S.showAllProviders=true}else if(toggle.dataset.marketToggle==='services')S.showAllServices=!S.showAllServices;else S.showAllProviders=!S.showAllProviders;draw()},true);
const baseServicesPage=servicesPage;servicesPage=function(){const d=S.data||{},ar=rtl(),providers=(d.providers||S.providers||[]).slice(0,6),pins=providers.map(p=>{const portrait=p.avatar_data?`<img src="${p.avatar_data}" alt="">`:icon('user',16),service=ar?p.name_ar:p.name_en;return `<button class="map-pin provider-pin" data-map-provider="${p.id}" aria-label="${esc(p.full_name)}"><i class="map-provider-avatar">${portrait}</i><span class="map-provider-copy"><b>${esc(p.full_name)}</b><small>${esc(service||'')} · ${esc(p.location||'')}</small></span></button>`}).join('');return baseServicesPage().replace(/<button class="map-pin pin-\d+"[^>]*>.*?<\/button>/g,'').replace('<span class="my-location"></span>',`<span class="my-location"></span><div class="map-pins-grid provider-pins-grid">${pins}</div>`)};
document.addEventListener('click',e=>{const pin=e.target.closest?.('[data-map-provider]');if(!pin||S.user?.role!=='customer')return;const provider=(S.data?.providers||S.providers||[]).find(p=>p.id===+pin.dataset.mapProvider);if(!provider)return;e.preventDefault();S.chosen=provider;S.view='book';S.navCollapsed=false;draw()},true);
const orderStatusMeta=status=>({Completed:{key:'done',label:rtl()?'مكتملة':'Completed',icon:'check'},'In Progress':{key:'progress',label:rtl()?'قيد التنفيذ':'In progress',icon:'clock'},'On the way':{key:'progress',label:rtl()?'في الطريق':'On the way',icon:'clock'},Accepted:{key:'progress',label:rtl()?'تم القبول':'Accepted',icon:'check'},Pending:{key:'pending',label:rtl()?'بانتظار الموافقة':'Waiting',icon:'clock'},Rejected:{key:'cancelled',label:rtl()?'ملغاة':'Cancelled',icon:'x'}}[status]||{key:'pending',label:statusText(status),icon:'clock'});
const orderVisualActions=(r,providerMode)=>{let a=`<button class="order-outline" data-track="${r.id}">${rtl()?'عرض التفاصيل':'View details'}</button>`;if(providerMode){if(r.status==='Pending')a=`<button class="primary small" data-status="${r.id}:Accepted">${icon('check',15)} ${t('accept')}</button><button class="danger small" data-status="${r.id}:Rejected">${t('reject')}</button>`+a;else if(r.status==='Accepted')a=`<button class="order-outline" data-status="${r.id}:On the way">${t('onway')}</button>`+a;else if(r.status==='On the way')a=`<button class="order-outline" data-status="${r.id}:In Progress">${t('progress')}</button>`+a;else if(r.status==='In Progress')a=`<button class="primary small" data-status="${r.id}:Completed">${t('complete')}</button>`+a}else if(r.status==='Completed'){const invoice=(S.data?.invoices||[]).find(i=>Number(i.request_id)===Number(r.id)),review=(S.data?.reviews||[]).find(x=>Number(x.request_id)===Number(r.id)),paid=invoice?invoice.payment_status!=='Pending':!!r.payment_id;if(!invoice&&!r.payment_id)a+=`<span class="order-state-note">${rtl()?'بانتظار الفاتورة':'Awaiting invoice'}</span>`;else if(!paid)a+=`<button class="primary small" data-nav="invoices">${rtl()?'ادفع الفاتورة':'Pay invoice'}</button>`;else a+=review?`<span class="order-state-note">★ ${review.rating} ${rtl()?'تم التقييم':'Rated'}</span>`:`<button class="primary small" data-rate="${r.id}">${t('rate')}</button>`}return a};
const serviceWorkPhoto=name=>/electric/i.test(name||'')?'/assets/service-electrician.png?v=1':/plumb/i.test(name||'')?'/assets/service-plumber.png?v=1':'';
const orderVisualRow=(r,providerMode)=>{const meta=orderStatusMeta(r.status),service=rtl()?r.name_ar:r.name_en||r.name_ar,person=providerMode?r.customer_name:r.provider_name||'',date=[r.date,r.time].filter(Boolean).join(' · '),photo=serviceWorkPhoto(r.name_en);return `<article class="orders-visual-row"><div class="order-visual-main"><div class="order-service-thumb">${photo?`<img src="${photo}" alt="${esc(service)}">`:serviceIcon(r.name_en||'General Maintenance')}</div><div class="order-visual-copy"><div class="order-visual-title"><b>${esc(service)}</b><span>${esc(r.location||'')}</span></div><div class="order-visual-person"><i>${icon('user',14)}</i><span>${esc(person)}</span><em>${icon('clock',13)} ${esc(date)}</em></div></div></div><div class="order-visual-side"><span class="order-status ${meta.key}">${icon(meta.icon,14)} ${meta.label}</span><small>${esc(date||'')}</small><div class="order-visual-actions">${orderVisualActions(r,providerMode)}</div></div></article>`};
function ordersPage(){const items=S.data.requests||[],provider=S.user.role==='provider',active=S.orderFilter||'all',filters=[['all',rtl()?'الكل':'All'],['progress',rtl()?'قيد التنفيذ':'In progress'],['done',rtl()?'مكتملة':'Completed'],['cancelled',rtl()?'ملغاة':'Cancelled']],match=r=>active==='all'||orderStatusMeta(r.status).key===active,shown=items.filter(match),counts={all:items.length,progress:items.filter(r=>orderStatusMeta(r.status).key==='progress').length,done:items.filter(r=>orderStatusMeta(r.status).key==='done').length,cancelled:items.filter(r=>orderStatusMeta(r.status).key==='cancelled').length},invoices=S.data.invoices||[],pending=!provider&&invoices.find(i=>i.payment_status==='Pending'),notice=pending?`<article class="notice clay invoice-ready"><i>${invoiceIcon(20)}</i><div><b>${t('newInvoiceReady')}</b><span>${esc(rtl()?pending.name_ar:pending.name_en||t('invoices'))} · ${invoiceMoney(pending.total_amount)}</span></div><button class="primary small" data-nav="invoices">${t('viewInvoice')}</button></article>`:'';return shell(`<section class="orders-reference"><main class="orders-board"><header class="orders-reference-head"><div><h1>${invoiceIcon(29)} ${t('orders')}</h1><p>${rtl()?'تابع كل طلباتك وحالتها وتفاصيلها في مكان واحد':'Track every request and its details in one place.'}</p></div><div class="orders-app-logo"><img src="/assets/engedny-mark.png?v=2" alt="${t('brand')}"><span><b>${t('brand')}</b><small>ENGEDNY</small></span></div></header>${notice}<div class="order-filter-bar">${filters.map(([key,label])=>`<button class="order-filter ${active===key?'selected':''}" data-order-filter="${key}"><span>${label}</span><b>${counts[key]}</b></button>`).join('')}</div><section class="orders-visual-list">${shown.length?shown.map(r=>orderVisualRow(r,provider)).join(''):`<div class="empty clay">${t('noOrders')}</div>`}</section></main><aside class="orders-help-rail"><section class="orders-art-card"><img src="/assets/orders-clipboard-illustration.png?v=1" alt=""><p>${rtl()?'استمتع بخدمة أفضل لمنزلك':'A better service experience for your home'}</p></section><section class="orders-support-card"><b>${rtl()?'مساعدة سريعة':'Quick help'}</b><button data-nav="services">${icon('search',17)} ${rtl()?'اطلب خدمة':'Request a service'}</button><button data-track="${items[0]?.id||''}">${icon('clock',17)} ${rtl()?'تتبع طلبي':'Track my request'}</button><button data-nav="chat">${icon('chat',17)} ${rtl()?'تواصل مع الدعم':'Contact support'}</button></section></aside></section>`) }
document.addEventListener('click',e=>{const filter=e.target.closest?.('[data-order-filter]');if(!filter||!S.user)return;e.preventDefault();S.orderFilter=filter.dataset.orderFilter;draw()},true);
const invoiceParts=i=>{try{const parts=JSON.parse(i.materials||'[]');return Array.isArray(parts)?parts.filter(x=>x&&x.name):[]}catch{return i.materials?[{name:i.materials,price:Number(i.materials_amount)||0}]:[]}};
const materialRow=()=>`<div class="material-row"><input data-material-name placeholder="${rtl()?'اسم القطعة':'Part name'}"><input data-material-price type="number" min="0" step="0.01" placeholder="${rtl()?'السعر':'Price'}"><button type="button" class="remove-material" aria-label="${rtl()?'حذف القطعة':'Remove part'}">×</button></div>`;
function invoicesPage(){const d=S.data,provider=S.user.role==='provider',invoices=d.invoices||[],issued=new Set(invoices.map(x=>x.request_id)),eligible=(d.requests||[]).filter(r=>r.status==='Completed'&&!issued.has(r.id));const create=provider&&eligible.length?`<form id="invoiceFormV2" class="form clay invoice-form"><div class="page-title"><h2>${invoiceIcon(22)} ${t('createInvoice')}</h2><p>${rtl()?'أضيفي كل قطعة وسعرها، وسيُحسب الإجمالي تلقائيًا.':'Add each part and its price; totals are calculated automatically.'}</p></div><label>${t('completedRequest')}<select name="requestId" required>${eligible.map(r=>`<option value="${r.id}">${esc(rtl()?r.name_ar:r.name_en)} · ${esc(r.customer_name)}</option>`).join('')}</select></label><label>${t('workDone')}<textarea name="workDone" required></textarea></label><section class="materials-builder"><div class="materials-builder-head"><b>${t('materials')}</b><span>${rtl()?'كل قطعة بسعرها':'Each part with its price'}</span></div><div id="materialRows">${materialRow()}</div><div class="materials-builder-foot"><button type="button" class="ghost small" id="addMaterial">+ ${rtl()?'إضافة قطعة':'Add part'}</button><b>${t('materialsAmount')}: <span id="materialsLiveTotal">${invoiceMoney(0)}</span></b></div></section><label>${t('laborAmount')}<input name="laborAmount" type="number" min="0" step="0.01" required></label><label>${t('paymentChoice')}<select name="paymentMethod"><option value="Cash">${t('cash')}</option><option value="Card">${t('card')}</option><option value="Wallet">${t('wallet')}</option></select></label><button class="primary">${t('issueInvoice')}</button><div class="error" id="invoiceError"></div></form>`:'';return shell(`<div class="page-title"><h1>${invoiceIcon(25)} ${t('invoices')}</h1></div>${create}<section class="invoice-list">${invoices.length?invoices.map(invoiceCard).join(''):`<div class="empty clay">${t('noInvoices')}</div>`}</section>`)}
function invoiceCard(i){const provider=S.user.role==='provider',paid=i.payment_status!=='Pending',net=Number(i.total_amount)-Number(i.platform_fee),parts=invoiceParts(i);const action=provider?(paid?(i.commission_status==='Pending'?`<div class="invoice-actions"><b>${t('commissionPending')}: ${invoiceMoney(i.platform_fee)}</b><button class="ghost small" data-commission="${i.id}:InstaPay">${t('instapay')}</button><button class="ghost small" data-commission="${i.id}:Wallet">${t('wallet')}</button></div>`:`<span class="invoice-success">${icon('check',15)} ${t('commissionDone')}</span>`):`<span class="status">${t('paymentPending')}</span>`):paid?`<span class="invoice-success">${icon('check',15)} ${esc(i.payment_status)}</span>`:`<button class="primary small" data-invoice-pay="${i.id}:${i.payment_method}">${t('payNow')}</button>`;return `<article class="invoice-card clay"><div class="invoice-title"><i>${invoiceIcon(22)}</i><div><b>${esc(rtl()?i.name_ar:i.name_en||t('invoices'))}</b><span>${esc(provider?i.customer_name:i.provider_name||'')} · ${i.date||''}</span></div><strong>${invoiceMoney(i.total_amount)}</strong></div><div class="invoice-lines"><p><b>${t('workDone')}</b><span>${esc(i.work_done)}</span></p>${parts.length?`<div class="invoice-parts"><b>${t('materials')}</b>${parts.map(p=>`<span>${esc(p.name)}<em>${invoiceMoney(p.price)}</em></span>`).join('')}</div>`:''}</div><div class="invoice-summary"><span>${t('laborAmount')}<b>${invoiceMoney(i.labor_amount)}</b></span><span>${t('materialsAmount')}<b>${invoiceMoney(i.materials_amount)}</b></span><span>${t('total')}<b>${invoiceMoney(i.total_amount)}</b></span>${provider?`<span>${t('technicianShare')}<b>${invoiceMoney(net)}</b></span>`:''}</div><div class="invoice-footer"><small>${t('paymentChoice')}: ${invoicePaymentLabel(i.payment_method)}</small><div class="invoice-actions"><button class="ghost small" data-export-invoice="${i.id}">${invoiceIcon(15)} ${t('exportInvoice')}</button>${action}</div></div></article>`}
function exportInvoice(id){const i=(S.data?.invoices||[]).find(x=>x.id===Number(id));if(!i)return;const w=window.open('','_blank'),parts=invoiceParts(i);if(!w)return alert(rtl()?'اسمحي بفتح النافذة لتصدير الفاتورة.':'Allow pop-ups to export the invoice.');const rows=parts.map(p=>`<tr><td>${esc(p.name)}</td><td>${invoiceMoney(p.price)}</td></tr>`).join('')||`<tr><td>-</td><td>${invoiceMoney(0)}</td></tr>`;w.document.write(`<!doctype html><html dir="${rtl()?'rtl':'ltr'}"><head><meta charset="utf-8"><title>Engedny Invoice #${i.id}</title><style>body{font-family:Tahoma,Arial;margin:42px;color:#102a56}.head{display:flex;justify-content:space-between;border-bottom:3px solid #2563eb;padding-bottom:18px}.mark{font-size:24px;font-weight:800;color:#2563eb}table{width:100%;border-collapse:collapse;margin:20px 0}td,th{padding:12px;border-bottom:1px solid #dbeafe;text-align:start}.total{font-size:18px;font-weight:800;color:#2563eb}</style></head><body><div class="head"><div class="mark">انجدني | Engedny</div><div>Invoice #${i.id}</div></div><p><b>${esc(t('workDone'))}:</b> ${esc(i.work_done)}</p><table><thead><tr><th>${esc(t('materials'))}</th><th>${rtl()?'السعر':'Price'}</th></tr></thead><tbody>${rows}</tbody></table><table><tr><th>${esc(t('laborAmount'))}</th><td>${invoiceMoney(i.labor_amount)}</td></tr><tr><th>${esc(t('materialsAmount'))}</th><td>${invoiceMoney(i.materials_amount)}</td></tr><tr><th>${esc(t('total'))}</th><td class="total">${invoiceMoney(i.total_amount)}</td></tr></table><script>setTimeout(()=>print(),250)<\/script></body></html>`);w.document.close()}
const updateMaterialsTotal=()=>{const total=[...document.querySelectorAll('[data-material-price]')].reduce((sum,x)=>sum+(Number(x.value)||0),0),out=$('#materialsLiveTotal');if(out)out.textContent=invoiceMoney(total)};
document.addEventListener('click',e=>{if(e.target?.id==='addMaterial'){$('#materialRows')?.insertAdjacentHTML('beforeend',materialRow());return}const remove=e.target.closest?.('.remove-material');if(remove){const rows=document.querySelectorAll('.material-row');if(rows.length>1)remove.closest('.material-row')?.remove();else{remove.closest('.material-row')?.querySelectorAll('input').forEach(x=>x.value='')}updateMaterialsTotal()}},true);
document.addEventListener('input',e=>{if(e.target?.matches?.('[data-material-price]'))updateMaterialsTotal()});
document.addEventListener('submit',async e=>{if(e.target?.id!=='invoiceFormV2')return;e.preventDefault();const error=$('#invoiceError'),parts=[...document.querySelectorAll('.material-row')].map(row=>({name:row.querySelector('[data-material-name]')?.value.trim(),price:Number(row.querySelector('[data-material-price]')?.value)})).filter(x=>x.name||Number.isFinite(x.price));if(parts.some(x=>!x.name||!Number.isFinite(x.price)||x.price<0)){if(error)error.textContent=rtl()?'اكتبي اسم وسعر كل قطعة.':'Enter a name and price for every part.';return}try{const f=Object.fromEntries(new FormData(e.target));await api.invoice({...f,providerId:S.user.id,materialItems:parts});S.data=null;draw()}catch(err){if(error)error.textContent=err.message}},true);
function exportInvoice(id){const i=(S.data?.invoices||[]).find(x=>x.id===Number(id));if(!i)return;const w=window.open('','_blank'),parts=invoiceParts(i),thing=rtl()?'الحاجة':'Item',priceLabel=rtl()?'السعر':'Price';if(!w)return alert(rtl()?'اسمحي بفتح النافذة لتصدير الفاتورة.':'Allow pop-ups to export the invoice.');const rows=parts.map((p,n)=>`<tr><td class="branch"><i></i><span>${esc(p.name)}</span></td><td>${invoiceMoney(p.price)}</td></tr>`).join('')||`<tr><td class="branch"><i></i><span>-</span></td><td>${invoiceMoney(0)}</td></tr>`;w.document.write(`<!doctype html><html dir="${rtl()?'rtl':'ltr'}"><head><meta charset="utf-8"><title>Engedny Invoice #${i.id}</title><style>body{font-family:Tahoma,Arial;margin:42px;color:#102a56}.head{display:flex;justify-content:space-between;border-bottom:3px solid #2563eb;padding-bottom:18px}.mark{font-size:24px;font-weight:800;color:#2563eb}table{width:100%;border-collapse:collapse;margin:20px 0}td,th{padding:12px;border-bottom:1px solid #dbeafe;text-align:start}.parts-title{margin:22px 0 0;font-weight:800}.branch{position:relative;display:flex;align-items:center;gap:10px}.branch:before{content:"";position:absolute;inset-inline-start:9px;top:-13px;bottom:-13px;width:1px;background:#bfdbfe}.branch i{width:14px;height:1px;background:#bfdbfe;z-index:1}.branch span{background:#fff;padding-inline:2px}.total{font-size:18px;font-weight:800;color:#2563eb}</style></head><body><div class="head"><div class="mark">انجدني | Engedny</div><div>Invoice #${i.id}</div></div><p><b>${esc(t('workDone'))}:</b> ${esc(i.work_done)}</p><p class="parts-title">${esc(t('materials'))}</p><table><thead><tr><th>${thing}</th><th>${priceLabel}</th></tr></thead><tbody>${rows}</tbody></table><table><tr><th>${esc(t('laborAmount'))}</th><td>${invoiceMoney(i.labor_amount)}</td></tr><tr><th>${esc(t('materialsAmount'))}</th><td>${invoiceMoney(i.materials_amount)}</td></tr><tr><th>${esc(t('total'))}</th><td class="total">${invoiceMoney(i.total_amount)}</td></tr></table><script>setTimeout(()=>print(),250)<\/script></body></html>`);w.document.close()}
