function exportInvoice(id){const i=(S.data?.invoices||[]).find(x=>x.id===Number(id));if(!i)return;const w=window.open('','_blank'),parts=invoiceParts(i),provider=S.user.role==='provider',tech=i.provider_name||(provider?S.data.user.full_name:''),customer=i.customer_name||(!provider?S.data.user.full_name:''),partLabel=rtl()?'القطع':'Parts',priceLabel=rtl()?'السعر':'Price',brand=`${location.origin}/assets/engedny-mark.png?v=1`;if(!w)return alert(rtl()?'اسمحي بفتح النافذة لتصدير الفاتورة.':'Allow pop-ups to export the invoice.');const rows=parts.map(p=>`<tr><td class="branch"><i></i><span>${esc(p.name)}</span></td><td>${invoiceMoney(p.price)}</td></tr>`).join('')||`<tr><td class="branch"><i></i><span>-</span></td><td>${invoiceMoney(0)}</td></tr>`;w.document.write(`<!doctype html><html dir="${rtl()?'rtl':'ltr'}"><head><meta charset="utf-8"><title>Engedny Invoice #${i.id}</title><style>body{font-family:Tahoma,Arial;margin:42px;color:#102a56}.head{display:flex;justify-content:space-between;align-items:center;border-bottom:3px solid #2563eb;padding-bottom:18px}.brand{display:flex;align-items:center;gap:10px;font-size:24px;font-weight:800;color:#2563eb}.brand img{width:46px;height:46px;object-fit:contain}table{width:100%;border-collapse:collapse;margin:20px 0}td,th{padding:12px;border-bottom:1px solid #dbeafe;text-align:start}.meta{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;padding:16px;background:#f8fbff;border:1px solid #dbeafe;border-radius:12px;margin-top:20px}.meta span{display:grid;gap:4px;font-size:12px;color:#64748b}.meta b{color:#102a56}.branch{position:relative;display:flex;align-items:center;gap:10px}.branch:before{content:"";position:absolute;inset-inline-start:9px;top:-13px;bottom:-13px;width:1px;background:#bfdbfe}.branch i{width:14px;height:1px;background:#bfdbfe;z-index:1}.branch span{background:#fff;padding-inline:2px}.total{font-size:18px;font-weight:800;color:#2563eb}</style></head><body><div class="head"><div class="brand"><img src="${brand}" alt="Engedny">انجدني | Engedny</div><div>Invoice #${i.id}</div></div><div class="meta"><span><b>${rtl()?'الفني':'Technician'}</b>${esc(tech)}</span><span><b>${rtl()?'العميل':'Customer'}</b>${esc(customer)}</span><span><b>${rtl()?'التاريخ':'Date'}</b>${esc(i.date||i.created_at||'')}</span></div><p><b>${esc(t('workDone'))}:</b> ${esc(i.work_done)}</p><table><thead><tr><th>${partLabel}</th><th>${priceLabel}</th></tr></thead><tbody>${rows}</tbody></table><table><tr><th>${esc(t('laborAmount'))}</th><td>${invoiceMoney(i.labor_amount)}</td></tr><tr><th>${esc(t('total'))}</th><td class="total">${invoiceMoney(i.total_amount)}</td></tr></table><script>setTimeout(()=>print(),250)<\/script></body></html>`);w.document.close()}
function invoicesPage(){const d=S.data,provider=S.user.role==='provider',invoices=d.invoices||[],issued=new Set(invoices.map(x=>x.request_id)),eligible=(d.requests||[]).filter(r=>r.status==='Completed'&&!issued.has(r.id)),thing=rtl()?'القطع':'Parts',priceLabel=rtl()?'السعر':'Price';const create=provider&&eligible.length?`<form id="invoiceFormV2" class="form clay invoice-form"><div class="page-title"><h2>${invoiceIcon(22)} ${t('createInvoice')}</h2></div><label>${t('completedRequest')}<select name="requestId" required>${eligible.map(r=>`<option value="${r.id}">${esc(rtl()?r.name_ar:r.name_en)} · ${esc(r.customer_name)}</option>`).join('')}</select></label><label>${t('workDone')}<textarea name="workDone" required></textarea></label><section class="materials-builder"><div class="materials-builder-head"><b>${t('materials')}</b></div><div class="material-columns"><span>${thing}</span><span>${priceLabel}</span></div><div id="materialRows">${materialRow()}</div><div class="materials-builder-foot"><button type="button" class="ghost small" id="addMaterial">+ ${rtl()?'إضافة':'Add'}</button><b>${t('materialsAmount')}: <span id="materialsLiveTotal">${invoiceMoney(0)}</span></b></div></section><label>${t('laborAmount')}<input name="laborAmount" type="number" min="0" step="0.01" required></label><label>${t('paymentChoice')}<select name="paymentMethod"><option value="Cash">${t('cash')}</option><option value="Card">${t('card')}</option><option value="Wallet">${t('wallet')}</option></select></label><button class="primary">${t('issueInvoice')}</button><div class="error" id="invoiceError"></div></form>`:'';return shell(`<div class="page-title"><h1>${invoiceIcon(25)} ${t('invoices')}</h1></div>${create}<section class="invoice-list">${invoices.length?invoices.map(invoiceCard).join(''):`<div class="empty clay">${t('noInvoices')}</div>`}</section>`)}
function invoiceCard(i){const provider=S.user.role==='provider',paid=i.payment_status!=='Pending',net=Number(i.total_amount)-Number(i.platform_fee),parts=invoiceParts(i),thing=rtl()?'الحاجة':'Item',priceLabel=rtl()?'السعر':'Price';const action=provider?(paid?(i.commission_status==='Pending'?`<div class="invoice-actions"><b>${t('commissionPending')}: ${invoiceMoney(i.platform_fee)}</b><button class="ghost small" data-commission="${i.id}:InstaPay">${t('instapay')}</button><button class="ghost small" data-commission="${i.id}:Wallet">${t('wallet')}</button></div>`:`<span class="invoice-success">${icon('check',15)} ${t('commissionDone')}</span>`):`<span class="status">${t('paymentPending')}</span>`):paid?`<span class="invoice-success">${icon('check',15)} ${esc(i.payment_status)}</span>`:`<button class="primary small" data-invoice-pay="${i.id}:${i.payment_method}">${t('payNow')}</button>`;return `<article class="invoice-card clay"><div class="invoice-title"><i>${invoiceIcon(22)}</i><div><b>${esc(rtl()?i.name_ar:i.name_en||t('invoices'))}</b><span>${esc(provider?i.customer_name:i.provider_name||'')} · ${i.date||''}</span></div><strong>${invoiceMoney(i.total_amount)}</strong></div><div class="invoice-lines"><p><b>${t('workDone')}</b><span>${esc(i.work_done)}</span></p>${parts.length?`<div class="invoice-parts tree-parts"><b>${t('materials')}</b><div class="material-columns"><span>${thing}</span><span>${priceLabel}</span></div>${parts.map(p=>`<span><i></i><label>${esc(p.name)}</label><em>${invoiceMoney(p.price)}</em></span>`).join('')}</div>`:''}</div><div class="invoice-summary"><span>${t('laborAmount')}<b>${invoiceMoney(i.labor_amount)}</b></span><span>${t('materialsAmount')}<b>${invoiceMoney(i.materials_amount)}</b></span><span>${t('total')}<b>${invoiceMoney(i.total_amount)}</b></span>${provider?`<span>${t('technicianShare')}<b>${invoiceMoney(net)}</b></span>`:''}</div><div class="invoice-footer"><small>${t('paymentChoice')}: ${invoicePaymentLabel(i.payment_method)}</small><div class="invoice-actions"><button class="ghost small" data-export-invoice="${i.id}">${invoiceIcon(15)} ${t('exportInvoice')}</button>${action}</div></div></article>`}
